1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = { itemType: string; amount: number };
9	
10	export type Incident = { cause: string; damages: Damage[] };
11	
12	export type QuoteStep = { op: "quote"; items: Item[] };
13	
14	export type ClaimStep = { op: "claim"; policy: number; incident: Incident };
15	
16	export type Step = QuoteStep | ClaimStep;
17	
18	export type Scenario = {
19	  customer: { yearsWithMHPCO: number };
20	  steps: Step[];
21	};
22	
23	export type QuoteResult = { premium: number };
24	
25	export type ClaimResult = { payout: number; remainingCap: number };
26	
27	export type StepResult = QuoteResult | ClaimResult;
28	
29	export type ScenarioResult = { results: StepResult[] };
30	
31	const PROCESSING_FEE = 5;
32	
33	// The MHPCO price list: one row per insurable item type.
34	type PriceListEntry = { insuranceValue: number; basePremium: number };
35	
36	const PRICE_LIST: Record<string, PriceListEntry> = {
37	  sword: { insuranceValue: 1000, basePremium: 100 },
38	  amulet: { insuranceValue: 600, basePremium: 60 },
39	  staff: { insuranceValue: 800, basePremium: 80 },
40	  potion: { insuranceValue: 400, basePremium: 40 },
41	  rune: { insuranceValue: 250, basePremium: 25 },
42	  moonstone: { insuranceValue: 250, basePremium: 25 },
43	};
44	
45	const priceListEntryOf = (item: Item): PriceListEntry => PRICE_LIST[item.type];
46	
47	const CURSE_SURCHARGE_RATE = 0.5;
48	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
49	const HIGH_ENCHANTMENT_THRESHOLD = 5;
50	
51	const basePremiumOf = (item: Item): number => priceListEntryOf(item).basePremium;
52	
53	// An item without an explicit enchantment level counts as unenchanted.
54	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
55	
56	const isEnchantedAtLeast = (item: Item, threshold: number): boolean =>
57	  enchantmentOf(item) >= threshold;
58	
59	const curseSurchargeRateOf = (item: Item): number => (item.cursed ? CURSE_SURCHARGE_RATE : 0);
60	
61	const highEnchantmentSurchargeRateOf = (item: Item): number =>
62	  isEnchantedAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0;
63	
64	const SURCHARGE_RATES = [curseSurchargeRateOf, highEnchantmentSurchargeRateOf];
65	
66	const totalSurchargeRateOf = (item: Item): number =>
67	  SURCHARGE_RATES.reduce((total, rateOf) => total + rateOf(item), 0);
68	
69	const premiumOf = (item: Item): number => basePremiumOf(item) * (1 + totalSurchargeRateOf(item));
70	
71	const BLOCK_SIZE = 3;
72	const PREMIUM_PER_BLOCK = 60;
73	
74	const groupByType = (items: Item[]): Item[][] => {
75	  const types = [...new Set(items.map((item) => item.type))];
76	  return types.map((type) => items.filter((item) => item.type === type));
77	};
78	
79	type ItemValuation = (item: Item) => number;
80	
81	const premiumOfSameTypeGroup = (sameTypeItems: Item[], valueOf: ItemValuation): number =>
82	  sameTypeItems.length === BLOCK_SIZE
83	    ? PREMIUM_PER_BLOCK
84	    : sameTypeItems.reduce((sum, item) => sum + valueOf(item), 0);
85	
86	const itemsPremium = (items: Item[], valueOf: ItemValuation): number =>
87	  groupByType(items).reduce((total, group) => total + premiumOfSameTypeGroup(group, valueOf), 0);
88	
89	const totalItemsPremium = (items: Item[]): number => itemsPremium(items, premiumOf);
90	
91	const policyBasePremium = (items: Item[]): number => itemsPremium(items, basePremiumOf);
92	
93	type Customer = { yearsWithMHPCO: number };
94	
95	type PolicyContext = { customer: Customer; quotesSoFar: number };
96	
97	const LOYALTY_DISCOUNT_RATE = -0.2;
98	const LOYALTY_YEARS_THRESHOLD = 2;
99	
100	const loyaltyRateOf = ({ customer }: PolicyContext): number =>
101	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? LOYALTY_DISCOUNT_RATE : 0;
102	
103	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
104	
105	const firstInsuranceRateOf = (_context: PolicyContext): number => FIRST_INSURANCE_SURCHARGE_RATE;
106	
107	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
108	
109	const followUpRateOf = ({ quotesSoFar }: PolicyContext): number =>
110	  quotesSoFar > 0 ? FOLLOW_UP_DISCOUNT_RATE : 0;
111	
112	const POLICY_RATES = [loyaltyRateOf, firstInsuranceRateOf, followUpRateOf];
113	
114	const totalPolicyRateOf = (context: PolicyContext): number =>
115	  POLICY_RATES.reduce((total, rateOf) => total + rateOf(context), 0);
116	
117	// MHPCO always rounds in its own favor: premiums it charges go up, payouts it owes go down.
118	const roundPremiumInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
119	
120	const roundPayoutInMHPCOsFavor = (amount: number): number => Math.floor(amount);
121	
122	const premiumFor = (items: Item[], context: PolicyContext): number =>
123	  roundPremiumInMHPCOsFavor(
124	    totalItemsPremium(items) +
125	      policyBasePremium(items) * totalPolicyRateOf(context) +
126	      PROCESSING_FEE,
127	  );
128	
129	const insuranceValueOf = (item: Item): number => priceListEntryOf(item).insuranceValue;
130	
131	const insuranceSumOf = (items: Item[]): number =>
132	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
133	
134	const CAP_FACTOR = 2;
135	
136	const capOf = (items: Item[]): number => insuranceSumOf(items) * CAP_FACTOR;
137	
138	const DEDUCTIBLE = 100;
139	
140	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
141	const HALF_REIMBURSEMENT_RATE = 0.5;
142	
143	const FULL_REIMBURSEMENT_RATE = 1;
144	
145	const reimbursementRateOf = (insuredItem: Item): number =>
146	  isEnchantedAtLeast(insuredItem, HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD)
147	    ? HALF_REIMBURSEMENT_RATE
148	    : FULL_REIMBURSEMENT_RATE;
149	
150	const payoutForDamage = (damage: Damage, insuredItem: Item): number =>
151	  damage.amount * reimbursementRateOf(insuredItem) - DEDUCTIBLE;
152	
153	const insuredItemFor = (damage: Damage, policyItems: Item[]): Item =>
154	  policyItems.find((item) => item.type === damage.itemType) as Item;
155	
156	const payoutForIncident = (incident: Incident, policyItems: Item[]): number =>
157	  incident.damages.reduce(
158	    (total, damage) => total + payoutForDamage(damage, insuredItemFor(damage, policyItems)),
159	    0,
160	  );
161	
162	type ScenarioState = { context: PolicyContext; results: StepResult[]; steps: Step[] };
163	
164	const policyItemsOf = (state: ScenarioState, step: ClaimStep): Item[] =>
165	  (state.steps[step.policy] as QuoteStep).items;
166	
167	const claimResultFor = (state: ScenarioState, step: ClaimStep): ClaimResult => {
168	  const policyItems = policyItemsOf(state, step);
169	  const payout = roundPayoutInMHPCOsFavor(payoutForIncident(step.incident, policyItems));
170	  return { payout, remainingCap: capOf(policyItems) - payout };
171	};
172	
173	const resultFor = (state: ScenarioState, step: Step): StepResult =>
174	  step.op === "quote"
175	    ? { premium: premiumFor(step.items, state.context) }
176	    : claimResultFor(state, step);
177	
178	const applyStep = (state: ScenarioState, step: Step): ScenarioState => ({
179	  ...state,
180	  context: { ...state.context, quotesSoFar: state.context.quotesSoFar + 1 },
181	  results: [...state.results, resultFor(state, step)],
182	});
183	
184	export function runScenario(scenario: Scenario): ScenarioResult {
185	  const initialState: ScenarioState = {
186	    context: { customer: scenario.customer, quotesSoFar: 0 },
187	    results: [],
188	    steps: scenario.steps,
189	  };
190	  return { results: scenario.steps.reduce(applyStep, initialState).results };
191	}
